package org.jlinalg.cli;

import java.io.*;
import java.nio.file.*;
import java.util.*;
import org.jlinalg.metagenomics.MaltIndexTaxonomy;
import org.jlinalg.metagenomics.MaltTaxonomy;

/** Captured native mapping stage; standalone development command, no upstream executable bundled. */
public final class MaltIndexTaxonomyCli {
    private MaltIndexTaxonomyCli() { }
    private static final String ACTION="Required action: retain the complete source index, mapping, derived index and diagnostics. Use only a permitted complete taxonomy-only BlastN source index whose taxonomy.idx is all zero and whose headers have no tax tags. Choose the accession namespace explicitly; supply a positive mapping for EVERY reference and taxa present in the complete source taxonomy. Use a NEW output directory. Read WARNINGS.md. This native alternative does not establish the authors' original MALT0.5.2 indexing behavior or biological findings. If the index, data or required Java environment cannot be supplied/installed where permitted, skip the dependent analysis.";
    private static final String WARNING="# Native MALT index alternative\n\nThis command creates a separately labelled derived index. It replaces the all-zero taxonomy mapping and adds explicit taxon tags to every reference header. It preserves every reference sequence, reference order, seed table, taxonomy tree/map and original source file. It validates complete input populations and refuses incomplete, conflicting or guessed accession mappings. It does not run MALT alignment, qualify RMA classification, reproduce the paper's original accession-map code path or establish biological absence.\n\nOriginal MALT0.5.2 package controls exited zero with all taxonomy IDs zero when organism-name parsing was disabled. Upstream commit88d1a6331f0a7c8e8df2cf4b8ce576eeb88cf745 (2021-08-04) registers the missing taxonomy mappings. Selecting this native alternative is an explicit method difference; do not present its output as an unchanged upstream0.5.2 index.\n\n"+ACTION+"\n";
    public static void main(String[] args){int code=run(args,System.out,System.err);if(code!=0)System.exit(code);}
    static int run(String[] args,PrintStream out,PrintStream error) {
        Path destination=null;boolean owned=false;
        try {
            if(args.length==1&&args[0].equals("--help")){out.println("Native MALT taxonomy-index mapping alternative\n--database COMPLETE_UNCLASSIFIED_INDEX --mapping FILE[.gz] --format two-column|ncbi-accession2taxid --namespace literal|accession|accession.version --out NEW_DIRECTORY\nTWO_COLUMN uses literal first-word reference IDs; NCBI requires its four-column header and an explicit accession column. No version suffix is stripped.\nLimits: --maximum-file-bytes 1000000000 --maximum-references 1000000 --maximum-reference-bases 100000000000 --maximum-mapping-rows 1000000000 --maximum-line-characters 1048576 --maximum-taxonomy-characters 100000000 --maximum-taxonomy-nodes 3000000 --maximum-taxonomy-depth 1024.\nRead-only full replay: --verify COMPLETE_BUNDLE\n"+ACTION);return 0;}
            Set<String> allowed=Set.of("--verify","--database","--mapping","--format","--namespace","--out","--maximum-file-bytes","--maximum-references","--maximum-reference-bases","--maximum-mapping-rows","--maximum-line-characters","--maximum-taxonomy-characters","--maximum-taxonomy-nodes","--maximum-taxonomy-depth");var options=new LinkedHashMap<String,String>();
            for(int i=0;i<args.length;i+=2)if(i+1>=args.length||!allowed.contains(args[i])||options.putIfAbsent(args[i],args[i+1])!=null)throw new IOException("Require unique complete options; see --help");
            if(options.containsKey("--verify")){if(!options.keySet().equals(Set.of("--verify")))throw new IOException("Full saved replay accepts --verify only");verify(Path.of(options.get("--verify")).toRealPath());out.println("VERIFIED_COMPLETE_NATIVE_MALT_INDEX_ALTERNATIVE; no upstream refit or producer authentication.\n"+ACTION);return 0;}
            if(!options.keySet().containsAll(Set.of("--database","--mapping","--format","--namespace","--out")))throw new IOException("Declare complete index, mapping, format, namespace and NEW output");
            destination=Path.of(options.get("--out")).toAbsolutePath().normalize();Path database=Path.of(options.get("--database")).toRealPath(),mapping=Path.of(options.get("--mapping")).toAbsolutePath().normalize();
            if(destination.startsWith(database)||database.startsWith(destination)||!destination.getParent().equals(destination.getParent().toRealPath()))throw new IOException("Source index and NEW output must not overlap; canonical output parent required");Files.createDirectory(destination);owned=true;
            var limits=limits(options);var format=format(options.get("--format"));var namespace=namespace(options.get("--namespace"));var original=MaltIndexTaxonomy.inventory(database,limits.fileBytes());var mapPin=MaltIndexTaxonomy.pin(mapping,limits.fileBytes());
            Path inputs=destination.resolve("inputs"),captured=inputs.resolve("index");Files.createDirectories(captured);for(String n:original.keySet())Files.copy(database.resolve(n),captured.resolve(n));Path copied=inputs.resolve(mapping.toString().endsWith(".gz")?"mapping.tsv.gz":"mapping.tsv");Files.copy(mapping,copied);
            if(!original.equals(MaltIndexTaxonomy.inventory(captured,limits.fileBytes()))||!mapPin.equals(MaltIndexTaxonomy.pin(copied,limits.fileBytes())))throw new IOException("Complete captured inputs differ");
            var result=MaltIndexTaxonomy.derive(captured,copied,format,namespace,destination.resolve("index"),limits);
            if(!original.equals(MaltIndexTaxonomy.inventory(database,limits.fileBytes()))||!mapPin.equals(MaltIndexTaxonomy.pin(mapping,limits.fileBytes())))throw new IOException("Original inputs changed during derivation");
            var report=new LinkedHashMap<String,Object>();report.put("status","complete-native-malt-index-taxonomy-alternative");report.put("format",options.get("--format"));report.put("namespace",options.get("--namespace"));report.put("mapping",destination.relativize(copied).toString().replace('\\','/'));report.put("limits",limitDocument(limits));report.put("scientific",result.document());report.put("upstream_alignment_executed",false);report.put("paper_original_index_path_qualified",false);report.put("biological_result_admitted",false);report.put("new_tool_credit",0);NextflowFiles.writeJson(destination.resolve("audit.json"),report);Files.writeString(destination.resolve("WARNINGS.md"),WARNING,StandardOpenOption.CREATE_NEW);
            NextflowFiles.writeJson(destination.resolve("COMPONENT_COMPLETED.json"),Map.of("status","complete-native-malt-index-taxonomy-alternative","files",inventory(destination,limits.fileBytes())));out.println("DERIVED_NATIVE_MALT_INDEX_ALTERNATIVE_COMPLETE: "+result.references()+" references, "+result.referenceBases()+" bases; read WARNINGS.md.\n"+ACTION);return 0;
        }catch(Exception failure) {
            error.println("MALT NATIVE INDEX FAIL2 NO RESULT ADMITTED: "+failure+"\n"+ACTION);
            if(owned)try{NextflowFiles.writeJson(destination.resolve("FAILURE.json"),Map.of("status","FAIL2_NO_RESULT_ADMITTED","error",failure.toString(),"required_action",ACTION));Files.writeString(destination.resolve("WARNINGS_FAILURE.md"),"# FAIL2 NO RESULT ADMITTED\n\n"+failure+"\n\n"+ACTION+"\n",StandardOpenOption.CREATE_NEW);}catch(IOException e){error.println("Retain console diagnostics; diagnostic write failed: "+e);}return 2;
        }
    }
    private static void verify(Path bundle)throws IOException {
        NextflowFiles.directory(bundle);var complete=NextflowFiles.object(NextflowFiles.json(bundle.resolve("COMPONENT_COMPLETED.json"),67108864));var report=NextflowFiles.object(NextflowFiles.json(bundle.resolve("audit.json"),67108864));String status="complete-native-malt-index-taxonomy-alternative";
        if(!status.equals(complete.get("status"))||!status.equals(report.get("status"))||!Boolean.FALSE.equals(report.get("upstream_alignment_executed"))||!Boolean.FALSE.equals(report.get("paper_original_index_path_qualified"))||!Boolean.FALSE.equals(report.get("biological_result_admitted"))||NextflowFiles.integer(report.get("new_tool_credit"),0,0)!=0)throw new IOException("Unsupported native mapping scope");
        var savedLimits=NextflowFiles.object(report.get("limits"));var options=new LinkedHashMap<String,String>();for(var e:savedLimits.entrySet())options.put(NextflowFiles.text(e.getKey()),Objects.toString(e.getValue()));var limits=limits(options);if(!NextflowJson.json(savedLimits).equals(NextflowJson.json(limitDocument(limits))))throw new IOException("Saved complete capacities differ");
        if(!NextflowJson.json(complete.get("files")).equals(NextflowJson.json(inventory(bundle,limits.fileBytes()))))throw new IOException("Complete saved bundle inventory differs");String map=NextflowFiles.member(NextflowFiles.text(report.get("mapping")));if(!Set.of("inputs/mapping.tsv","inputs/mapping.tsv.gz").contains(map))throw new IOException("Unknown mapping binding");
        var result=MaltIndexTaxonomy.audit(bundle.resolve("inputs/index"),bundle.resolve(map),format(NextflowFiles.text(report.get("format"))),namespace(NextflowFiles.text(report.get("namespace"))),bundle.resolve("index"),limits);
        if(!NextflowJson.json(result.document()).equals(NextflowJson.json(report.get("scientific")))||!NextflowJson.json(complete.get("files")).equals(NextflowJson.json(inventory(bundle,limits.fileBytes()))))throw new IOException("Full saved native mapping recomputation differs");
    }
    private static Map<String,NextflowFiles.Pin> inventory(Path root,long maximum)throws IOException {var result=new TreeMap<String,NextflowFiles.Pin>();try(var files=Files.walk(root)){for(Path p:files.filter(p->!Files.isDirectory(p,LinkOption.NOFOLLOW_LINKS)).toList()){String name=root.relativize(p).toString().replace('\\','/');if(name.equals("COMPONENT_COMPLETED.json"))continue;if(result.size()>=30000)throw new IOException("Complete bundle member capacity exceeded");result.put(name,NextflowFiles.pin(p,maximum,()->{}));}}return result;}
    private static MaltIndexTaxonomy.Format format(String value)throws IOException {return switch(value){case "two-column"->MaltIndexTaxonomy.Format.TWO_COLUMN;case "ncbi-accession2taxid"->MaltIndexTaxonomy.Format.NCBI_ACCESSION2TAXID;default->throw new IOException("Explicit supported mapping format required");};}
    private static MaltIndexTaxonomy.Namespace namespace(String value)throws IOException {return switch(value){case "literal"->MaltIndexTaxonomy.Namespace.LITERAL;case "accession"->MaltIndexTaxonomy.Namespace.ACCESSION;case "accession.version"->MaltIndexTaxonomy.Namespace.ACCESSION_VERSION;default->throw new IOException("Explicit literal/accession/accession.version namespace required");};}
    private static MaltIndexTaxonomy.Limits limits(Map<String,String> o)throws IOException {return new MaltIndexTaxonomy.Limits(number(o,"--maximum-file-bytes",1000000000,1,1000000000000L),(int)number(o,"--maximum-references",1000000,1,Integer.MAX_VALUE),number(o,"--maximum-reference-bases",100000000000L,1,10000000000000L),number(o,"--maximum-mapping-rows",1000000000,1,Long.MAX_VALUE),(int)number(o,"--maximum-line-characters",1048576,1,16777216),new MaltTaxonomy.Limits(number(o,"--maximum-taxonomy-characters",100000000,1,1000000000),(int)number(o,"--maximum-taxonomy-nodes",3000000,4,10000000),(int)number(o,"--maximum-taxonomy-depth",1024,1,100000)));}
    private static long number(Map<String,String> o,String key,long fallback,long min,long max)throws IOException {long value;try{value=o.containsKey(key)?Long.parseLong(o.get(key)):fallback;}catch(NumberFormatException e){throw new IOException("Decimal integer required: "+key,e);}if(value<min||value>max)throw new IOException("Positive bounded complete capacity required: "+key);return value;}
    private static Map<String,Object> limitDocument(MaltIndexTaxonomy.Limits l){return Map.of("--maximum-file-bytes",l.fileBytes(),"--maximum-references",l.references(),"--maximum-reference-bases",l.referenceBases(),"--maximum-mapping-rows",l.mappingRows(),"--maximum-line-characters",l.lineCharacters(),"--maximum-taxonomy-characters",l.taxonomy().characters(),"--maximum-taxonomy-nodes",l.taxonomy().nodes(),"--maximum-taxonomy-depth",l.taxonomy().depth());}
}
